{"command": "cat > /prediction.json << 'EOF'
{
    "vllm/attention/ops/triton_decode_attention.py": {
        "_fwd_kernel_stage2": "@triton.jit\ndef _fwd_kernel_stage2(\n    Mid_O,\n    o,\n    lse,\n    B_Seqlen,\n    stride_mid_ob,\n    stride_mid_oh,\n    stride_mid_os,\n    stride_obs,\n    stride_oh,\n    stride_lse_bs,\n    NUM_KV_SPLITS: tl.constexpr,\n    BLOCK_DV: tl.constexpr,\n    Lv: tl.constexpr,\n):\n    cur_batch = tl.program_id(0)\n    cur_head = tl.program_id(1)\n\n    cur_batch_seq_len = tl.load(B_Seqlen + cur_batch)\n\n    offs_d = tl.arange(0, BLOCK_DV)\n    mask_d = offs_d < Lv\n\n    e_sum = 0.0\n    e_max = -float(\"inf\")\n    acc = tl.zeros([BLOCK_DV], dtype=tl.float32)\n\n    offs_v = cur_batch * stride_mid_ob + cur_head * stride_mid_oh + offs_d\n    offs_logic = cur_batch * stride_mid_ob + cur_head * stride_mid_oh + Lv\n\n    for split_kv_id in range(0, NUM_KV_SPLITS):\n        kv_len_per_split = tl.cdiv(cur_batch_seq_len, NUM_KV_SPLITS)\n        split_kv_start = kv_len_per_split * split_kv_id\n        split_kv_end = tl.minimum(split_kv_start + kv_len_per_split,\n                                  cur_batch_seq_len)\n\n        if split_kv_end > split_kv_start:\n            tv = tl.load(Mid_O + offs_v + split_kv_id * stride_mid_os,\n                         mask=mask_d,\n                         other=0.0)\n            tlogic = tl.load(Mid_O + offs_logic + split_kv_id * stride_mid_os)\n            n_e_max = tl.maximum(tlogic, e_max)\n\n            old_scale = tl.exp(e_max - n_e_max)\n            acc *= old_scale\n            exp_logic = tl.exp(tlogic - n_e_max)\n            acc += exp_logic * tv\n\n            e_sum = e_sum * old_scale + exp_logic\n            e_max = n_e_max\n\n    # Store attention output\n    # Handle division by zero: if e_sum == 0, return 0\n    output = tl.where(e_sum != 0.0, acc / e_sum, 0.0)\n    tl.store(\n        o + cur_batch * stride_obs + cur_head * stride_oh + offs_d,\n        output,\n        mask=mask_d,\n    )\n    \n    # Compute and store LSE (Log-Sum-Exp)\n    # If e_sum == 0, log(e_sum) = -inf, and e_max = -inf, so result is -inf\n    lse_value = e_max + tl.log(e_sum)\n    tl.store(\n        lse + cur_batch * stride_lse_bs + cur_head,\n        lse_value,\n    )"
    }
}
EOF"}

